  rabbitmq: {name:'RabbitMQ',description:'Faire circuler les messages entre vos applications',category:'infra',spec:{image:'rabbitmq:4-management',ports:['5672:5672','15672:15672'],env:{RABBITMQ_DEFAULT_USER:'autodocker',RABBITMQ_DEFAULT_PASS:'__AUTO_PASSWORD__'},volumes:['rabbitmq_data:/var/lib/rabbitmq']}},
  memcached: {name:'Memcached',description:'Un cache léger pour accélérer vos applications',category:'data',spec:{image:'memcached:1.6-alpine',ports:['11211:11211']}},
  meilisearch: {name:'Meilisearch',description:'Un moteur de recherche pour vos applications',category:'data',spec:{image:'getmeili/meilisearch:v1.20',ports:['7700:7700'],env:{MEILI_ENV:'production',MEILI_MASTER_KEY:'__AUTO_PASSWORD__'},volumes:['meili_data:/meili_data']}}
