function catalogueText(value){return value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('fr');}
function orderedCatalogueKeys(catalogue){
  const position=new Map(CATALOGUE_PRIORITY.map((key,index)=>[key,index]));
  return Object.keys(catalogue).sort((a,b)=>(position.get(a)??1000)-(position.get(b)??1000)||(catalogue[a].name||a).localeCompare(catalogue[b].name||b,'fr'));
}
function catalogueMatches(catalogue,selected,filter='all',query=''){
  const chosen=new Set(selected),search=catalogueText(query.trim());
  return orderedCatalogueKeys(catalogue).filter(key=>{
    const service=catalogue[key];
    return (filter==='all'||filter==='selected'&&chosen.has(key)||service.category===filter||service.tags?.includes(filter)||filter==='ai'&&['rag','agents'].includes(service.category))
      &&catalogueText([service.name,service.description,key,CATALOGUE_TECHNICAL_COPY[key]||''].join(' ')).includes(search);
  });
}
function catalogueCounts(catalogue,selected,query=''){
  const result=Object.fromEntries(Object.keys(SERVICE_CATEGORIES).map(key=>[key,0])),chosen=new Set(selected);
  catalogueMatches(catalogue,selected,'all',query).forEach(key=>{result.all++;if(chosen.has(key))result.selected++;const category=catalogue[key].category||'infra';result[category]++;const extra=new Set(catalogue[key].tags||[]);if(['rag','agents'].includes(category))extra.add('ai');extra.delete(category);extra.forEach(tag=>{if(Object.hasOwn(result,tag))result[tag]++;});});
  return result;
}
function partitionSelection(keys,proposal=null){
  const explicit=new Set(keys),all=resolveServices(keys,proposal);
  return {chosen:all.filter(key=>explicit.has(key)),automatic:all.filter(key=>!explicit.has(key))};
}

