  async function hfJSON(path){
    const response=await fetch('https://huggingface.co/api/models'+path,{credentials:'omit',signal:AbortSignal.timeout(18000)});
    if(!response.ok)throw new Error(response.status===429?'Hugging Face limite temporairement les recherches. Réessayez dans un moment.':'Ce dépôt n’est pas accessible publiquement ou Hugging Face ne répond pas.');
    return response.json();
  }
