  async function loadHFRepository(repository){
    const request=++hfRepoRequest;
    $('hf-file-picker').hidden=true;showError('hf-error','');$('hf-status').textContent='Lecture des versions de '+repository+'…';
    try{
      if(!/^[A-Za-z0-9_-]+\/[A-Za-z0-9._-]+$/.test(repository))throw new Error('Indiquez un dépôt sous la forme auteur/nom-du-depot.');
      const data=await hfJSON('/'+repository.split('/').map(encodeURIComponent).join('/'));
      if(request!==hfRepoRequest||!modelDialog.open)return;
      if(data.gated||data.private)throw new Error('Ce dépôt nécessite une autorisation. Choisissez un dépôt GGUF public pour ce téléchargement automatique.');
      const files=huggingFaceFiles(data);if(!files.length)throw new Error('Aucun fichier GGUF autonome compatible trouvé. Les fichiers découpés et projecteurs vision ne sont pas proposés.');
      hfRepository=repository;$('hf-file').replaceChildren();files.forEach(filename=>{const option=document.createElement('option');option.value=filename;option.textContent=modelFileLabel(filename);$('hf-file').append(option);});
      $('hf-selected-repository').textContent=repository;$('hf-repository-link').href='https://huggingface.co/'+repository;
      $('hf-results').hidden=true;$('hf-file-picker').hidden=false;$('hf-status').textContent=files.length+' versions disponibles. Votre choix sera conservé après validation.';chooseHFFile();
    }catch(error){if(request===hfRepoRequest&&modelDialog.open){showError('hf-error',error.message);$('hf-status').textContent='Essayez un autre dépôt ou utilisez un identifiant depuis le catalogue Ollama.';}}
  }
  async function searchHF(){
    const query=$('hf-search').value.trim();if(!query||!modelDialog.open)return;
    const request=++hfSearchRequest;hfRepoRequest++;$('hf-file-picker').hidden=true;$('hf-results').hidden=false;$('hf-results').replaceChildren();showError('hf-error','');$('hf-status').textContent='Recherche de modèles GGUF…';$('hf-search-button').disabled=true;
    try{
      const direct=query.replace(/^https:\/\/(?:huggingface\.co|hf\.co)\//,'').replace(/\/$/,'');
      if(/^[A-Za-z0-9_-]+\/[A-Za-z0-9._-]+$/.test(direct)){await loadHFRepository(direct);return;}
      const data=await hfJSON('?'+new URLSearchParams({search:query,filter:'gguf',limit:'8',sort:'downloads',direction:'-1'}));
      if(request!==hfSearchRequest||!modelDialog.open)return;
      const results=(Array.isArray(data)?data:[]).filter(item=>typeof item.id==='string'&&/^[A-Za-z0-9_-]+\/[A-Za-z0-9._-]+$/.test(item.id)&&!item.private&&!item.gated);
      results.forEach(item=>{
        const button=document.createElement('button');button.type='button';const text=document.createElement('span'),title=document.createElement('strong'),description=document.createElement('small'),action=document.createElement('span');
        const [author,name]=item.id.split('/');title.textContent=name.replace(/[-_]GGUF$/i,'');description.textContent=author+' · GGUF';text.append(title,description);action.textContent='Voir les versions →';action.className='hf-result-action';button.append(text,action);button.addEventListener('click',()=>loadHFRepository(item.id));$('hf-results').append(button);
      });
      $('hf-status').textContent=results.length?results.length+' dépôts trouvés. Choisissez-en un pour voir ses versions.':'Aucun dépôt public trouvé. Essayez un autre nom.';
    }catch(error){if(request===hfSearchRequest&&modelDialog.open){showError('hf-error',error.name==='TimeoutError'?'Hugging Face ne répond pas. Réessayez dans un moment.':error.message);$('hf-status').textContent='La recherche n’a pas abouti.';}}
    finally{if(request===hfSearchRequest)$('hf-search-button').disabled=false;}
  }
  $('hf-search-button').addEventListener('click',searchHF);$('hf-search').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();searchHF();}});
  $('hf-file').addEventListener('change',chooseHFFile);
