    $('professional-ai-review-links').replaceChildren();(ai.connections||[]).forEach(connection=>{const li=document.createElement('li');li.textContent=(INFRA_SERVICES[connection.from]?.name||connection.from)+' → '+(INFRA_SERVICES[connection.to]?.name||connection.to)+' · '+connection.endpoint;$('professional-ai-review-links').append(li);});
