    (ingress.routes||[]).forEach(route=>{const row=document.createElement('li');const code=document.createElement('code');code.textContent=(ingress.protocol||'http')+'://'+route.host+':'+ingress.port;const target=document.createElement('span');target.textContent=' → '+(INFRA_SERVICES[route.service]?.name||route.service)+':'+route.port;row.append(code,target);$('ingress-review-routes').append(row);});
