    $('ai-proposal').hidden=!candidate || state.aiPending || state.aiQuestions;
    if ($('ai-proposal').hidden) return;
    const presentation=proposalPresentation(candidate.payload,candidate.metadata);
    $('ai-proposal-title').textContent=presentation.title;
    $('ai-proposal-text').textContent=presentation.summary;
    $('proposal-stale').hidden=candidate.prompt===$('infra-prompt').value.trim();
    $('ai-proposal-groups').replaceChildren();
