    $('summary-panel').hidden=state.mode==='ai';$('ai-process-panel').hidden=state.mode!=='ai';
    $('ai-process-title').textContent=process.title;$('ai-process-message').textContent=process.message;
    $('ai-process-label').textContent=process.title==='Architecture retenue'?'Validée':process.canUse?'À valider':'Brouillon';
    $('ai-process-brief').textContent=prompt.length>200?prompt.slice(0,200)+'…':prompt;$('ai-process-brief').hidden=!prompt;
    document.querySelectorAll('[data-ai-stage]').forEach(row=>{const current=Number(row.dataset.aiStage)===process.stage;row.classList.toggle('complete',Number(row.dataset.aiStage)<process.stage);if(current)row.setAttribute('aria-current','step');else row.removeAttribute('aria-current');});
    const candidate=state.aiCandidate;
