    if(!$('ai-process-groups').hidden)proposalPresentation(candidate.payload,candidate.metadata).groups.forEach(group=>{const row=document.createElement('div');const name=document.createElement('span');name.textContent=group.name;const count=document.createElement('b');count.textContent=String(group.services.length);row.append(name,count);$('ai-process-groups').append(row);});
    $('use-ai-proposal').hidden=!candidate || !!candidate.applied;$('use-ai-proposal').disabled=!process.canUse;
