    $('review-ai-proposal').disabled=!hasValidName() || state.aiPending || state.pending || !accepted;
    const mobile=document.querySelector('.mobile-selection');mobile.setAttribute('href',state.mode==='ai'?'#ai-process-panel':'#summary-panel');
