  window.addEventListener('pagehide',()=>aiController?.abort());
  $('ai-propose').addEventListener('click',async()=>{
    const prompt=$('infra-prompt').value.trim();if(!prompt||state.aiPending)return;
    state.aiPending=true;$('ai-propose').disabled=true;$('ai-propose').textContent='Préparation de la proposition…';$('ai-propose').classList.add('busy');$('infra-prompt').disabled=true;$('ai-progress').textContent='L’IA choisit les services adaptés. Cela peut prendre un moment.';showError('ai-error','');$('trial-signup').hidden=true;$('ai-proposal').hidden=true;$('ai-clarification').hidden=true;$('ai-propose').setAttribute('aria-busy','true');updateSummary();
    aiController=new AbortController();$('ai-cancel').hidden=false;$('ai-cancel').disabled=false;
    try{
      const data=await proposeInfrastructureWithAI(api,prompt,{signal:aiController.signal,onProgress:job=>{
        $('ai-progress').textContent=job.reconnecting?'Connexion momentanément interrompue · reprise du suivi en cours…':job.state==='queued'?'Votre demande attend son tour · position '+job.position+' dans la file.':job.state==='running'?'Conception en cours · '+job.active+' génération'+(job.active>1?'s':'')+' active'+(job.active>1?'s':'')+'.':$('ai-progress').textContent;
      }});
      if (data.questions?.length) {renderClarification(data);return;}
      state.aiQuestions=false;const payload=data.payload;
      if(!Array.isArray(payload?.services)||!payload.services.length||payload.services.some(service=>!service || typeof service.key!=='string'))throw new Error('L’IA n’a pas proposé de services utilisables. Précisez votre besoin ou choisissez-les manuellement.');
      state.aiCandidate=prepareAICandidate(data,prompt);registerProposalServices(payload);
      renderCatalogue();
      $('ai-progress').textContent='Proposition prête. Examinez-la, puis choisissez « Utiliser cette architecture » pour la retenir.';
    }catch(error){if(error.name==='AbortError')$('ai-progress').textContent='Demande annulée. Vous pouvez modifier votre besoin.';else if(error.code==='guest_quota_exhausted'){$('trial-signup').hidden=false;$('ai-progress').textContent='Deux demandes IA gratuites utilisées aujourd’hui. Votre demande reste en place.';window.TrialAccount?.open('signup');}else{showError('ai-error',error.message);$('ai-progress').textContent='Le choix manuel reste disponible.';}}
    finally{aiController=null;$('ai-cancel').hidden=true;state.aiPending=false;updateAIAction();$('ai-propose').classList.remove('busy');$('infra-prompt').disabled=false;$('ai-propose').setAttribute('aria-busy','false');updateSummary();window.TrialAccount?.refresh();}
  });
