    const combined=$('infra-prompt').value+'\nPrécision : '+answer;if(Array.from(combined.trim()).length>2000){showError('ai-error','Votre demande dépasse 2 000 caractères. Raccourcissez-la avant de compléter.');$('infra-prompt').focus();return;}$('infra-prompt').value=combined;
